import org.apache.http.HttpHost

class Bad {
    fun createHost(name: String): HttpHost {
        return HttpHost(name) // bad: default port -1, no protocol
    }
}

import org.apache.http.HttpHost

fun createHosts(names: List<String>): List<HttpHost> =
    names.map {
        HttpHost(it) // bad: created per element without port/protocol
    }

import org.apache.http.HttpHost

fun createHosts(names: List<String>): List<HttpHost> =
    names.map { HttpHost(it, 443, "https") }
